#!/usr/bin/env python3
"""Writes test/data/grid.usda: a synthetic scene large enough to span several scan morsels and output chunks.

The scene is /Grid with 50 rows of 60 cells (3,051 prims). Cell (r, c) is translated to (c, r, 0), so the expected
results of a query can be computed by hand. Run from the repository root:

    python3 scripts/generate_grid_scene.py
"""

import os

ROWS = 50
COLUMNS = 60


def main():
    lines = [
        "#usda 1.0",
        "(",
        '    defaultPrim = "Grid"',
        '    doc = "Generated by scripts/generate_grid_scene.py"',
        '    upAxis = "Z"',
        ")",
        "",
        'def Xform "Grid"',
        "{",
    ]
    for row in range(ROWS):
        lines.append(f'    def Xform "Row_{row:02d}"')
        lines.append("    {")
        for column in range(COLUMNS):
            lines.append(f'        def Xform "Cell_{column:02d}"')
            lines.append("        {")
            lines.append(f"            double3 xformOp:translate = ({column}, {row}, 0)")
            lines.append('            uniform token[] xformOpOrder = ["xformOp:translate"]')
            lines.append("        }")
        lines.append("    }")
    lines.append("}")
    lines.append("")

    path = os.path.join("test", "data", "grid.usda")
    with open(path, "w") as f:
        f.write("\n".join(lines))
    print(f"wrote {path}: {1 + ROWS + ROWS * COLUMNS} prims")


if __name__ == "__main__":
    main()
